import { format } from 'date-fns';
import { enUS } from 'date-fns/locale';
const localeMap = {
    en: enUS,
};
export function getDateFnsLocale(code) {
    return localeMap[code] ?? enUS;
}
export function registerLocale(code, locale) {
    localeMap[code] = locale;
}
export function formatDate(date, pattern, localeCode = 'en') {
    return format(date, pattern, { locale: getDateFnsLocale(localeCode) });
}
export function getWeekdayLabels(weekStartsOn, localeCode = 'en') {
    const locale = getDateFnsLocale(localeCode);
    const labels = [];
    for (let i = 0; i < 7; i++) {
        const dayIndex = ((weekStartsOn + i) % 7);
        const refDate = new Date(2024, 0, dayIndex === 0 ? 7 : dayIndex);
        labels.push(format(refDate, 'EEEEE', { locale }));
    }
    return labels;
}
export function getMonthLabels(localeCode = 'en') {
    const locale = getDateFnsLocale(localeCode);
    return Array.from({ length: 12 }, (_, i) => format(new Date(2024, i, 1), 'MMM', { locale }));
}
